import dns_codec as d

header = {"id": 0x1234, "qr": True, "opcode": 0, "aa": True, "tc": False,
          "rd": True, "ra": True, "z": 0, "rcode": 0,
          "qdcount": 1, "ancount": 2, "nscount": 1, "arcount": 1}
q = {"name": "example.com.", "qtype": 1, "qclass": 1}
a1 = {"name": "example.com.", "type": 1, "class": 1, "ttl": 300, "address": "192.0.2.1"}
a2 = {"name": "example.com.", "type": 28, "class": 1, "ttl": 300, "address": "2001:db8::1"}
ns = {"name": "example.com.", "type": 2, "class": 1, "ttl": 300, "target": "ns1.example.com."}
cn = {"name": "www.example.com.", "type": 5, "class": 1, "ttl": 60, "target": "example.com."}
msg = {"header": header, "questions": [q], "answers": [a1, a2],
       "authorities": [ns], "additionals": [cn]}

wire = d.encode_message(msg)
print("wire len:", len(wire))
back = d.decode_message(wire)
assert back == msg, back
assert list(back.keys()) == ["header", "questions", "answers", "authorities", "additionals"]
assert list(back["header"].keys()) == list(d.HEADER_FIELDS)
assert list(back["questions"][0].keys()) == ["name", "qtype", "qclass"]
assert list(back["answers"][0].keys()) == ["name", "type", "class", "ttl", "address"]
assert list(back["authorities"][0].keys()) == ["name", "type", "class", "ttl", "target"]
print("roundtrip OK")

# determinism
assert d.encode_message(msg) == wire
print("deterministic OK")

# compression pointers in decode: answer name = pointer to offset 12
wire2 = bytearray(wire)
# rebuild manually: header + question, then answer with pointer name 0xC00C
hdr = d.encode_header({**header, "ancount": 1, "nscount": 0, "arcount": 0})
qw = d.encode_question(q)
rr = b"\xc0\x0c" + d.encode_resource_record(a1)[len(d.encode_name("example.com.")):]
m2 = hdr + qw + rr
dec = d.decode_message(m2)
assert dec["answers"][0]["name"] == "example.com."
assert dec["answers"][0]["address"] == "192.0.2.1"
print("compression pointer OK")

# count mismatch
bad = dict(msg); bad["header"] = {**header, "qdcount": 2}
try:
    d.encode_message(bad); assert False
except d.DNSArgumentError as e: print("count mismatch:", e)

# missing / unknown top-level keys
for bad in ({"header": header}, {**msg, "extra": 1}):
    try:
        d.encode_message(bad); assert False
    except d.DNSArgumentError as e: print("shape:", e)

# non-sequence section
try:
    d.encode_message({**msg, "questions": "nope"}); assert False
except d.DNSArgumentError as e: print("section type:", e)

# non-bytes decode
try:
    d.decode_message("x"); assert False
except d.DNSArgumentError as e: print("non-bytes:", e)

# oversized decode
try:
    d.decode_message(b"\x00" * 65536); assert False
except d.DNSArgumentError as e: print("oversize:", e)

# truncated header
try:
    d.decode_message(b"\x00" * 11); assert False
except d.DNSMessageError as e: print("short header:", e)

# truncated section (counts demand entries that aren't there)
try:
    d.decode_message(hdr); assert False
except d.DNSMessageError as e: print("truncated section:", e)

# trailing bytes
try:
    d.decode_message(wire + b"\x00"); assert False
except d.DNSMessageError as e: print("trailing:", e)

# unsupported type inside message
mx = {"name": "example.com.", "type": 15, "class": 1, "ttl": 0}
hdr2 = d.encode_header({**header, "qdcount": 0, "ancount": 1, "nscount": 0, "arcount": 0})
rr_bad = d.encode_name("example.com.") + (15).to_bytes(2,"big") + (1).to_bytes(2,"big") + (0).to_bytes(4,"big") + (4).to_bytes(2,"big") + b"\x01\x02\x03\x04"
try:
    d.decode_message(hdr2 + rr_bad); assert False
except d.DNSMessageError as e: print("unsupported type:", e)

# input not mutated
import copy
snapshot = copy.deepcopy(msg)
d.encode_message(msg)
assert msg == snapshot
print("no mutation OK")
EOF

